<script setup lang="ts">import { ref,onMounted } from 'vue';import { api } from '../../api';const items=ref<any[]>([]);onMounted(async()=>items.value=await api.favorites())</script><template><section class="content-page"><div class="eyebrow">ACCOUNT / FAVORITES</div><h1>我的收藏</h1><div v-if="items.length" class="result-grid"><article v-for="item in items" :key="item.favorite_id" class="feature-card"><span class="card-index">{{item.target_type}}</span><h2>{{item.target_name}}</h2><p>收藏于 {{item.created_at}}</p></article></div><div v-else class="state-box">还没有收藏内容。</div></section></template>
